def _read_as_dask_or_memory(elem):
    try:
        return read_elem_as_dask(elem)
    except ImportError:
        return read_elem(elem)


def read_as_backed(group: ZarrGroup | H5Group, *, as_dask: bool = False):
    """
    Read the group until
    BaseCompressedSparseDataset, Array or EAGER_TYPES are encountered.

    If ``as_dask`` is set, arrays are read lazily when dask is available.
    """

    def callback(func, elem_name: str, elem, iospec):
        if iospec.encoding_type in SPARSE_MATRIX:
            if as_dask:
                return _read_as_dask_or_memory(elem)
            return sparse_dataset(elem)
        elif iospec.encoding_type in EAGER_TYPES:
            return read_elem(elem)
        elif iospec.encoding_type == "array":
            if as_dask:
                return _read_as_dask_or_memory(elem)
            return elem
        elif iospec.encoding_type == "dict":
            return {k: read_as_backed(v, as_dask=as_dask) for k, v in elem.items()}
        else:
            return func(elem)

    return read_dispatched(group, callback=callback)


def _df_index(df: ZarrGroup | H5Group) -> pd.Index:
    index_key = df.attrs["_index"]
    return pd.Index(read_elem(df[index_key]))

